    for (const action of ACTIONS) {
      const required = ROLE_MATRIX[action];
40→      for (const role of ROLES) {
        const expected = ROLE_RANK[role] >= ROLE_RANK[required];
        expect(
          can(makeActor({ role, userId: ALICE }), action, foreignOwned),
