    expect(can(viewer, "notification:manage", own)).toBe(true);
    expect(can(viewer, "notification:manage", other)).toBe(true);
  });

  it("does not escalate a project action for the project lead", () => {
    const led: PermissionResource = {
      kind: "project",
      orgId: ORG_A,
      projectId: PROJECT,
