/**
 * Lead changes are their own permission. A viewer who currently leads the
 * project may hand it off, but the person they name must themselves be
 * allowed to update the project.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const member = await memberRepo.findMember(input.orgId, input.leadId);
    if (member === null || member.status !== "active") {
      throw new NotFoundError("Member", input.leadId);
    }
    assertCan(
      { userId: member.userId, orgId: member.orgId, role: member.role },
      "project:update",
      projectResource(project),
    );
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}","tool_output_for_prompt":"The file /private/tmp/bench-scratch/690daa0d-dbce-45f9-9e37-27f56dcbbb9f/src/server/services/project-service.ts has been updated successfully.","tool_output_for_prompt_concise":"The file /private/tmp/bench-scratch/690daa0d-dbce-45f9-9e37-27f56dcbbb9f/src/server/services/project-service.ts has been updated.","absolute_path":"/private/tmp/bench-scratch/690daa0d-dbce-45f9-9e37-27f56dcbbb9f/src/server/services/project-service.ts","edits":{"details":[{"old_string":"  return projectRepo.updateProject(input);
